mapper.select:
select *
from pilipili.video_barrage
where file_id = #{fileId}
order by ${orderByField}

select *

    ,vi.video_name, vi.video_cover, u.user_name

from pilipili.video_barrage vb

    inner join pilipili.video_info vi on vb.video_id = vi.video_id
    left join pilipili.user u on vb.user_id = u.user_id



        vb.video_id = #{query.videoId}


        and vi.user_id = #{query.videoUserId}


        and vi.video_name like concat ('%', #{query.videoNameFuzzy}, '%')



    order by ${query.orderByField}

select count(*)
from pilipili.video_barrage
where video_id = #{videoId} and user_id = #{userId}

select *
from pilipili.video_barrage
where file_id = #{fileId}
  and `time` >= #{timeMin}
  and `time` < #{timeMax}
order by `time` asc, barrage_id asc

select max(`time`)
from pilipili.video_barrage
where file_id = #{fileId}
